import json

# The transformation rule:
# - Each non-1 value creates a vertical column going UPWARD from its source position
# - Column pattern: [N, 1, 1, 1] (N at farthest-up, then 1s)
# - Columns extend approximately 4 rows above the source row

source_row = 6
width = 11
height = 9

result = [[0]*width for _ in range(height)]

# Background: 0 everywhere except source row has 1s
for r in range(height):
    if r == source_row:
        # Source row: 1s with special values at non-1 positions
        for c in range(width):
            result[r][c] = 1

            # Special values at cols 1,3,7,9
            if c in [1, 3, 7, 9]:
                if c == 1 or c == 9:
                    result[r][c] = 2
                elif c == 3 or c == 7:
                    result[r][c] = 8

    else:
        # Add vertical columns going up from source row
        for c, val in [(1, 2), (3, 8), (7, 8), (9, 2)]:
            # Fill rows 2,3,4,5 (4 rows above source)
            for dr in range(4, 0, -1):  # Distance 4,3,2,1
                ri = source_row - dr
                if dr == 1:
                    result[ri][c] = val
                else:
                    result[ri][c] = 1

print("Final prediction:")
for row in result:
    print(row)
print(f"\nJSON: {json.dumps(result)}")

